  "$APPLY" "$SRC_6CH_TIF" "$TMPDIR/issue-1671.tif" \
  3 1 1 1 1 \
  "$TMPDIR/hbo-IIccProfileConnectionConditions-getEmissiveObserver-IccPcc_cpp-Line293.icc" \
  40

